insert into units (id, course_id, title_ar, summary_ar, sort_order, origin, source_id) values
 ('8361b6a7-29bb-550f-a0af-c1cf5639c1e8', '00000000-0000-0000-0000-000000000b01', 'الفصل الأول: التيار الكهربي وقانون أوم وقانونا كيرشوف', 'المقاومة والتوصيل والدائرة المغلقة وقانونا كيرشوف.', 1, 'editorial', 'f5544f7e-917f-561f-a505-dc068c88a6c5'),
 ('dbf8af48-45ea-52f6-991a-31d7e595da89', '00000000-0000-0000-0000-000000000b01', 'الفصل الثاني: التأثير المغناطيسي للتيار الكهربي وأجهزة القياس الكهربية', 'المجال المغناطيسي للتيار والقوة والعزم وأجهزة القياس.', 2, 'editorial', 'f5544f7e-917f-561f-a505-dc068c88a6c5');
insert into lessons (id, unit_id, title_ar, overview_ar, objectives_ar, body, sort_order, origin, source_id) values ('41722711-2e18-5125-b1de-aefdedf6fc80', '8361b6a7-29bb-550f-a0af-c1cf5639c1e8', 'قانون أوم', 'الكتاب المدرسي ص 3–4', '["ربط الجهد والتيار والمقاومة بقانون أوم","تفسير ميل خط الجهد والتيار"]', '[{"type": "text", "text": "عند ثبوت درجة الحرارة يتناسب التيار المار في موصل طرديًا مع فرق الجهد بين طرفيه. ثابت التناسب هو مقلوب المقاومة، ولهذا يكون ميل خط V–I مساويًا لـ R."}, {"type": "formula", "tex": "V = I \\times R"}, {"type": "lab", "lab": "ohm-law"}, {"type": "text", "text": "جرّب بنفسك: ثبّت V وزد R: يقل التيار وينخفض ميل الخط. القراءة تظهر على الأميتر والفولتميتر."}]', 1, 'editorial', 'f5544f7e-917f-561f-a505-dc068c88a6c5');
insert into concepts (id, lesson_id, title_ar, explanation_ar, formula_tex, sort_order, origin) values ('2ae8767b-a106-5332-9b82-3abe329e5d4c', '41722711-2e18-5125-b1de-aefdedf6fc80', 'قانون أوم', 'عند ثبوت درجة الحرارة يتناسب التيار المار في موصل طرديًا مع فرق الجهد بين طرفيه. ثابت التناسب هو مقلوب المقاومة، ولهذا يكون ميل خط V–I مساويًا لـ R.', 'V = I \times R', 1, 'editorial');
