insert into lessons (id, unit_id, title_ar, overview_ar, objectives_ar, body, sort_order, origin, source_id) values ('cc29a6a7-edc1-51f2-bb45-f1ccfd01a95f', '8361b6a7-29bb-550f-a0af-c1cf5639c1e8', 'مقاومة الموصل', 'الكتاب المدرسي ص 3–4', '["تحديد العوامل التي تتوقف عليها مقاومة الموصل","حساب المقاومة والتوصيلية من المقاومة النوعية"]', '[{"type": "text", "text": "مقاومة السلك تزيد مع طوله وتقل مع اتساع مقطعه، وتتحدد أيضًا بمادته عبر المقاومة النوعية ρ. التوصيلية σ هي مقلوب ρ، فكلما قلّت ρ زادت قدرة المادة على التوصيل."}, {"type": "formula", "tex": "R = \\rho_e \\dfrac{L}{A}"}, {"type": "lab", "lab": "resistance"}, {"type": "text", "text": "جرّب بنفسك: ضاعف الطول ثم ضاعف المساحة وقارن التغير في R، ثم بدّل المادة."}]', 2, 'editorial', 'f5544f7e-917f-561f-a505-dc068c88a6c5');
