insert into lessons (id, unit_id, title_ar, overview_ar, objectives_ar, body, sort_order, origin, source_id) values ('6cd16913-ffb9-592a-a0b7-68dde8e2d8ba', '8361b6a7-29bb-550f-a0af-c1cf5639c1e8', 'التوصيل على التوالي', 'الكتاب المدرسي ص 4–5', '["حساب المقاومة المكافئة عند التوصيل على التوالي","تحديد توزيع الجهد على المقاومات"]', '[{"type": "text", "text": "تتصل المقاومات طرفًا بطرف فيمر فيها التيار نفسه، وينقسم فرق جهد المصدر بينها بنسب قيمها. المقاومة المكافئة أكبر من أكبر مقاومة في المجموعة، وإن تساوت N مقاومات قيمة كل منها R فإن R′ = N R."}, {"type": "formula", "tex": "R'' = R_1 + R_2 + R_3"}, {"type": "lab", "lab": "series"}, {"type": "text", "text": "جرّب بنفسك: غيّر R₁ وراقب أي فولتميتر يتأثر: الأميتر ثابت، والجهد يتوزع."}]', 3, 'editorial', 'f5544f7e-917f-561f-a505-dc068c88a6c5');
insert into concepts (id, lesson_id, title_ar, explanation_ar, formula_tex, sort_order, origin) values ('1872d0e6-f90c-5050-ae37-c11a6e23502b', '6cd16913-ffb9-592a-a0b7-68dde8e2d8ba', 'التوصيل على التوالي', 'تتصل المقاومات طرفًا بطرف فيمر فيها التيار نفسه، وينقسم فرق جهد المصدر بينها بنسب قيمها. المقاومة المكافئة أكبر من أكبر مقاومة في المجموعة، وإن تساوت N مقاومات قيمة كل منها R فإن R′ = N R.', 'R'' = R_1 + R_2 + R_3', 1, 'editorial');
