insert into lessons (id, unit_id, title_ar, overview_ar, objectives_ar, body, sort_order, origin, source_id) values ('0ec1adaf-eaa6-56e7-8143-e4bf012dfebe', '8361b6a7-29bb-550f-a0af-c1cf5639c1e8', 'التوصيل على التوازي', 'الكتاب المدرسي ص 6–7', '["حساب المقاومة المكافئة عند التوصيل على التوازي","تحديد توزيع التيار على الفروع"]', '[{"type": "text", "text": "تتصل بدايات المقاومات معًا ونهاياتها معًا، فيكون فرق الجهد نفسه على كل فرع، وينقسم التيار الكلي بحسب القيم: الجزء الأكبر في أصغر مقاومة. المقاومة المكافئة أقل من أصغر مقاومة، وإن تساوت N مقاومات فإن R′ = R ÷ N."}, {"type": "formula", "tex": "\\dfrac{1}{R''} = \\dfrac{1}{R_1} + \\dfrac{1}{R_2} + \\dfrac{1}{R_3}"}, {"type": "lab", "lab": "parallel"}, {"type": "text", "text": "جرّب بنفسك: صغّر R₁ وراقب كيف يزيد تياره، وكيف تنخفض المقاومة المكافئة."}]', 4, 'editorial', 'f5544f7e-917f-561f-a505-dc068c88a6c5');
insert into concepts (id, lesson_id, title_ar, explanation_ar, formula_tex, sort_order, origin) values ('100688b7-87cf-5109-834c-a61b5c723660', '0ec1adaf-eaa6-56e7-8143-e4bf012dfebe', 'التوصيل على التوازي', 'تتصل بدايات المقاومات معًا ونهاياتها معًا، فيكون فرق الجهد نفسه على كل فرع، وينقسم التيار الكلي بحسب القيم: الجزء الأكبر في أصغر مقاومة. المقاومة المكافئة أقل من أصغر مقاومة، وإن تساوت N مقاومات فإن R′ = R ÷ N.', '\dfrac{1}{R''} = \dfrac{1}{R_1} + \dfrac{1}{R_2} + \dfrac{1}{R_3}', 1, 'editorial');
