insert into lessons (id, unit_id, title_ar, overview_ar, objectives_ar, body, sort_order, origin, source_id) values ('93ff80a1-311a-581d-906c-9d0536f58e59', '8361b6a7-29bb-550f-a0af-c1cf5639c1e8', 'الدائرة المغلقة', 'الكتاب المدرسي ص 8–9', '["تطبيق قانون أوم على الدائرة المغلقة","حساب فرق الجهد بين قطبي البطارية"]', '[{"type": "text", "text": "للبطارية مقاومة داخلية r، فيضيع جزء من قوتها الدافعة داخلها. لذلك يكون فرق الجهد بين قطبيها أقل من V_B بمقدار I·r، ولا يساوي V_B إلا إذا لم يمر تيار."}, {"type": "formula", "tex": "I = \\dfrac{V_B}{R + r}"}, {"type": "lab", "lab": "closed-circuit"}, {"type": "text", "text": "جرّب بنفسك: زد r وانظر كيف يقل جهد القطبين، ثم زد R ليقل التيار ويقترب الجهد من V_B."}]', 5, 'editorial', 'f5544f7e-917f-561f-a505-dc068c88a6c5');
insert into concepts (id, lesson_id, title_ar, explanation_ar, formula_tex, sort_order, origin) values ('06204527-a93b-5e2e-a79e-35246747ed37', '93ff80a1-311a-581d-906c-9d0536f58e59', 'الدائرة المغلقة', 'للبطارية مقاومة داخلية r، فيضيع جزء من قوتها الدافعة داخلها. لذلك يكون فرق الجهد بين قطبيها أقل من V_B بمقدار I·r، ولا يساوي V_B إلا إذا لم يمر تيار.', 'I = \dfrac{V_B}{R + r}', 1, 'editorial');
