insert into lessons (id, unit_id, title_ar, overview_ar, objectives_ar, body, sort_order, origin, source_id) values ('cbebaebd-0811-5f09-b9d1-c62d70098d28', '8361b6a7-29bb-550f-a0af-c1cf5639c1e8', 'قانون كيرشوف الأول', 'الكتاب المدرسي ص 13', '["تطبيق قانون حفظ الشحنة عند نقطة تفرع","حساب تيار مجهول عند عقدة"]', '[{"type": "text", "text": "الشحنة لا تتراكم عند نقطة تفرع، فكل ما يدخلها من تيار يخرج منها. ولذلك يساوي مجموع التيارات الداخلة إلى العقدة مجموع التيارات الخارجة منها."}, {"type": "formula", "tex": "\\sum I_{in} = \\sum I_{out}"}, {"type": "lab", "lab": "kirchhoff-1"}, {"type": "text", "text": "جرّب بنفسك: غيّر I₁ وI₂ وI₃ وشاهد التيار المجهول I₄ يتغير ليحفظ التوازن."}]', 6, 'editorial', 'f5544f7e-917f-561f-a505-dc068c88a6c5');
