insert into lessons (id, unit_id, title_ar, overview_ar, objectives_ar, body, sort_order, origin, source_id) values ('2b7df936-1696-5e85-96f0-b621d6c502ae', '8361b6a7-29bb-550f-a0af-c1cf5639c1e8', 'قانون كيرشوف الثاني', 'الكتاب المدرسي ص 13–14', '["تطبيق قانون حفظ الطاقة على مسار مغلق","تحديد الاتجاه الفعلي للتيار من إشارة الناتج"]', '[{"type": "text", "text": "في أي مسار مغلق يساوي المجموع الجبري للقوى الدافعة المجموع الجبري لفروق الجهد I·R. نفترض اتجاهًا للتيار؛ فإن خرجت قيمته سالبة فاتجاهه الفعلي عكس المفروض."}, {"type": "formula", "tex": "\\sum V_B = \\sum I \\, R"}, {"type": "lab", "lab": "kirchhoff-2"}, {"type": "text", "text": "جرّب بنفسك: اجعل E₂ أكبر من E₁ فينعكس التيار، ثم ساوِ بينهما فيختفي."}]', 7, 'editorial', 'f5544f7e-917f-561f-a505-dc068c88a6c5');
