insert into lessons (id, unit_id, title_ar, overview_ar, objectives_ar, body, sort_order, origin, source_id) values ('bd6fc2cc-94a4-519b-ac2b-803dfaf4a919', 'dbf8af48-45ea-52f6-991a-31d7e595da89', 'المجال حول سلك مستقيم', 'الكتاب المدرسي ص 26–27', '["حساب كثافة الفيض حول سلك مستقيم","تحديد اتجاه المجال بقاعدة اليد اليمنى"]', '[{"type": "text", "text": "يتولد حول السلك مجال مغناطيسي خطوط فيضه دوائر مركزها السلك. تزداد كثافة الفيض بزيادة التيار وتقل بالابتعاد عن السلك. لتعيين الاتجاه اقبض السلك باليد اليمنى بحيث يشير الإبهام لاتجاه التيار، فتدل الأصابع الملتفة على اتجاه المجال."}, {"type": "formula", "tex": "B = \\dfrac{\\mu I}{2\\pi d}"}, {"type": "lab", "lab": "wire-field"}, {"type": "text", "text": "جرّب بنفسك: ابعد عن السلك وراقب النقطة على المنحنى: B تتناسب عكسيًا مع d."}]', 1, 'editorial', 'f5544f7e-917f-561f-a505-dc068c88a6c5');
insert into concepts (id, lesson_id, title_ar, explanation_ar, formula_tex, sort_order, origin) values ('6c68d138-34cb-51b6-9752-c9f477164fab', 'bd6fc2cc-94a4-519b-ac2b-803dfaf4a919', 'المجال حول سلك مستقيم', 'يتولد حول السلك مجال مغناطيسي خطوط فيضه دوائر مركزها السلك. تزداد كثافة الفيض بزيادة التيار وتقل بالابتعاد عن السلك. لتعيين الاتجاه اقبض السلك باليد اليمنى بحيث يشير الإبهام لاتجاه التيار، فتدل الأصابع الملتفة على اتجاه المجال.', 'B = \dfrac{\mu I}{2\pi d}', 1, 'editorial');
