insert into lessons (id, unit_id, title_ar, overview_ar, objectives_ar, body, sort_order, origin, source_id) values ('82170756-0bc3-5036-9817-9493a4edde9d', 'dbf8af48-45ea-52f6-991a-31d7e595da89', 'المجال في مركز ملف دائري', 'الكتاب المدرسي ص 28–30', '["حساب كثافة الفيض عند مركز ملف دائري","تحديد القطبية بقاعدة البريمة اليمنى"]', '[{"type": "text", "text": "المجال الناتج عن ملف دائري يشبه مجال مغناطيس قصير. تتناسب كثافة الفيض عند مركزه طرديًا مع عدد اللفات وشدة التيار، وعكسيًا مع نصف القطر. تحدد قاعدة البريمة اليمنى القطبية: الوجه الذي يبدو التيار عنده عكس عقارب الساعة هو الشمالي."}, {"type": "formula", "tex": "B = \\dfrac{\\mu N I}{2 r}"}, {"type": "lab", "lab": "coil"}, {"type": "text", "text": "جرّب بنفسك: صغّر نصف القطر وزد عدد اللفات: كيف يتغير طول سهم المجال؟"}]', 2, 'editorial', 'f5544f7e-917f-561f-a505-dc068c88a6c5');
insert into concepts (id, lesson_id, title_ar, explanation_ar, formula_tex, sort_order, origin) values ('ae7d615b-2ed5-5625-87bb-d77250fa5e6c', '82170756-0bc3-5036-9817-9493a4edde9d', 'المجال في مركز ملف دائري', 'المجال الناتج عن ملف دائري يشبه مجال مغناطيس قصير. تتناسب كثافة الفيض عند مركزه طرديًا مع عدد اللفات وشدة التيار، وعكسيًا مع نصف القطر. تحدد قاعدة البريمة اليمنى القطبية: الوجه الذي يبدو التيار عنده عكس عقارب الساعة هو الشمالي.', 'B = \dfrac{\mu N I}{2 r}', 1, 'editorial');
insert into questions (id, concept_id, prompt_ar, explanation_ar, difficulty, origin) values ('bb42e645-42a5-5d11-9496-c2eed4418a83', 'ae7d615b-2ed5-5625-87bb-d77250fa5e6c', 'ملف دائري عدد لفاته 15 ونصف قطره 12 cm ويمر به تيار 4 A. احسب كثافة الفيض عند مركزه (μ = 4π×10⁻⁷). الإجابة بوحدة μT.', 'القانون المستخدم: B = μ N I / (2 r). الناتج الصحيح 314 μT.', 1, 'editorial');
