insert into lessons (id, unit_id, title_ar, overview_ar, objectives_ar, body, sort_order, origin, source_id) values ('4f25f30d-e2c9-51e6-9264-ff8165a379ab', 'dbf8af48-45ea-52f6-991a-31d7e595da89', 'المجال داخل ملف لولبي', 'الكتاب المدرسي ص 30–32', '["حساب كثافة الفيض داخل ملف لولبي","تفسير أثر عدد اللفات والطول وقلب الحديد"]', '[{"type": "text", "text": "الملف اللولبي لفات متتالية يشبه مجاله مجال مغناطيس قضيبي، وهو منتظم داخله. تتوقف كثافة الفيض على شدة التيار وعدد اللفات في وحدة الأطوال n = N/l، وتزداد كثيرًا عند وضع قلب من الحديد داخله لأن نفاذيته أكبر من الهواء. تحدد قطبيته بقاعدة اليد اليمنى."}, {"type": "formula", "tex": "B = \\dfrac{\\mu N I}{l}"}, {"type": "lab", "lab": "solenoid"}, {"type": "text", "text": "جرّب بنفسك: قصّر الطول مع ثبات عدد اللفات: تتركز اللفات وتزداد B."}]', 3, 'editorial', 'f5544f7e-917f-561f-a505-dc068c88a6c5');
insert into concepts (id, lesson_id, title_ar, explanation_ar, formula_tex, sort_order, origin) values ('74ddbf98-dda7-59d1-86b3-d7851b986746', '4f25f30d-e2c9-51e6-9264-ff8165a379ab', 'المجال داخل ملف لولبي', 'الملف اللولبي لفات متتالية يشبه مجاله مجال مغناطيس قضيبي، وهو منتظم داخله. تتوقف كثافة الفيض على شدة التيار وعدد اللفات في وحدة الأطوال n = N/l، وتزداد كثيرًا عند وضع قلب من الحديد داخله لأن نفاذيته أكبر من الهواء. تحدد قطبيته بقاعدة اليد اليمنى.', 'B = \dfrac{\mu N I}{l}', 1, 'editorial');
