insert into lessons (id, unit_id, title_ar, overview_ar, objectives_ar, body, sort_order, origin, source_id) values ('1332a260-9fbd-5bd7-9aad-07c5ce41a5a9', 'dbf8af48-45ea-52f6-991a-31d7e595da89', 'القوة على سلك في مجال', 'الكتاب المدرسي ص 33–36', '["حساب القوة المؤثرة على سلك يحمل تيارًا في مجال","تحديد اتجاه القوة بقاعدة اليد اليسرى لفلمنج"]', '[{"type": "text", "text": "السلك الذي يحمل تيارًا داخل مجال مغناطيسي تؤثر عليه قوة عمودية على كل من السلك والمجال. تزداد بزيادة B وI وطول السلك وجيب زاوية الميل، وتنعدم إذا كان السلك موازيًا للمجال. اتجاهها بقاعدة اليد اليسرى لفلمنج: السبابة للفيض والوسطى للتيار والإبهام للقوة. التسلا: كثافة الفيض التي تولد قوة نيوتن على متر من سلك يمر به أمبير."}, {"type": "formula", "tex": "F = B I L \\sin\\theta"}, {"type": "lab", "lab": "force-on-wire"}, {"type": "text", "text": "جرّب بنفسك: اجعل θ = 0 فتنعدم القوة، ثم θ = 90 فتبلغ أقصاها."}]', 4, 'editorial', 'f5544f7e-917f-561f-a505-dc068c88a6c5');
insert into concepts (id, lesson_id, title_ar, explanation_ar, formula_tex, sort_order, origin) values ('ac56fa8f-cfa2-5d5b-99c4-abbc4ac94d48', '1332a260-9fbd-5bd7-9aad-07c5ce41a5a9', 'القوة على سلك في مجال', 'السلك الذي يحمل تيارًا داخل مجال مغناطيسي تؤثر عليه قوة عمودية على كل من السلك والمجال. تزداد بزيادة B وI وطول السلك وجيب زاوية الميل، وتنعدم إذا كان السلك موازيًا للمجال. اتجاهها بقاعدة اليد اليسرى لفلمنج: السبابة للفيض والوسطى للتيار والإبهام للقوة. التسلا: كثافة الفيض التي تولد قوة نيوتن على متر من سلك يمر به أمبير.', 'F = B I L \sin\theta', 1, 'editorial');
