insert into lessons (id, unit_id, title_ar, overview_ar, objectives_ar, body, sort_order, origin, source_id) values ('251a4797-cadb-5ab4-ba95-d43d20fb11de', 'dbf8af48-45ea-52f6-991a-31d7e595da89', 'القوة بين سلكين متوازيين', 'الكتاب المدرسي ص 35–36', '["حساب القوة المتبادلة بين سلكين متوازيين","تحديد حالة التجاذب أو التنافر"]', '[{"type": "text", "text": "السلك الذي يحمل تيارًا يولد مجالًا يؤثر بقوة على سلك مجاور يحمل تيارًا. إذا كان التياران في الاتجاه نفسه تجاذب السلكان، وإذا تضادا تنافرا. تزداد القوة بزيادة التيارين وتقل بزيادة المسافة بينهما."}, {"type": "formula", "tex": "\\dfrac{F}{L} = \\dfrac{\\mu I_1 I_2}{2\\pi d}"}, {"type": "lab", "lab": "parallel-wires"}, {"type": "text", "text": "جرّب بنفسك: بدّل اتجاه التيارين (0 أو 1) وراقب انعكاس القوة، ثم قرّب السلكين."}]', 5, 'editorial', 'f5544f7e-917f-561f-a505-dc068c88a6c5');
insert into concepts (id, lesson_id, title_ar, explanation_ar, formula_tex, sort_order, origin) values ('b2355cd5-20e3-5243-996a-c93e54eac8ea', '251a4797-cadb-5ab4-ba95-d43d20fb11de', 'القوة بين سلكين متوازيين', 'السلك الذي يحمل تيارًا يولد مجالًا يؤثر بقوة على سلك مجاور يحمل تيارًا. إذا كان التياران في الاتجاه نفسه تجاذب السلكان، وإذا تضادا تنافرا. تزداد القوة بزيادة التيارين وتقل بزيادة المسافة بينهما.', '\dfrac{F}{L} = \dfrac{\mu I_1 I_2}{2\pi d}', 1, 'editorial');
insert into questions (id, concept_id, prompt_ar, explanation_ar, difficulty, origin) values ('6c43f310-b927-553a-ab0e-c92a2f98b4fa', 'b2355cd5-20e3-5243-996a-c93e54eac8ea', 'سلكان متوازيان يمر بهما تياران 13 A و3 A والمسافة بينهما 7 cm في الهواء. احسب القوة المتبادلة لكل متر من الطول. الإجابة بوحدة mN/m.', 'القانون المستخدم: F / L = μ I₁ I₂ / (2π d). الناتج الصحيح 0.111 mN/m.', 1, 'editorial');
