insert into lessons (id, unit_id, title_ar, overview_ar, objectives_ar, body, sort_order, origin, source_id) values ('e70db183-2c18-586d-be0c-56b01610cf00', 'dbf8af48-45ea-52f6-991a-31d7e595da89', 'عزم الازدواج على ملف', 'الكتاب المدرسي ص 36–38', '["حساب عزم الازدواج المؤثر على ملف","فهم عزم ثنائي القطب المغناطيسي"]', '[{"type": "text", "text": "الملف المستطيل الذي يحمل تيارًا في مجال منتظم تؤثر عليه قوتان متساويتان متضادتان تكوّنان ازدواجًا يديره. θ هي الزاوية بين العمودي على مستوى الملف (اتجاه عزم ثنائي القطب m_d) وخطوط الفيض. ينعدم العزم عندما يكون مستوى الملف عموديًا على الفيض، ويبلغ أقصاه عندما يوازيه. على هذه الفكرة تعمل أجهزة القياس والمحرك الكهربي."}, {"type": "formula", "tex": "\\tau = B I A N \\sin\\theta"}, {"type": "lab", "lab": "torque"}, {"type": "text", "text": "جرّب بنفسك: اجعل θ = 0 فيكون الملف عموديًا على الفيض ويتلاشى العزم."}]', 6, 'editorial', 'f5544f7e-917f-561f-a505-dc068c88a6c5');
insert into concepts (id, lesson_id, title_ar, explanation_ar, formula_tex, sort_order, origin) values ('d789658e-ef68-5dfc-be43-bf477be73871', 'e70db183-2c18-586d-be0c-56b01610cf00', 'عزم الازدواج على ملف', 'الملف المستطيل الذي يحمل تيارًا في مجال منتظم تؤثر عليه قوتان متساويتان متضادتان تكوّنان ازدواجًا يديره. θ هي الزاوية بين العمودي على مستوى الملف (اتجاه عزم ثنائي القطب m_d) وخطوط الفيض. ينعدم العزم عندما يكون مستوى الملف عموديًا على الفيض، ويبلغ أقصاه عندما يوازيه. على هذه الفكرة تعمل أجهزة القياس والمحرك الكهربي.', '\tau = B I A N \sin\theta', 1, 'editorial');
