insert into lessons (id, unit_id, title_ar, overview_ar, objectives_ar, body, sort_order, origin, source_id) values ('51038a5c-37b2-5255-b73b-3277760dde6e', 'dbf8af48-45ea-52f6-991a-31d7e595da89', 'تحويل الجلفانومتر إلى أميتر', 'الكتاب المدرسي ص 39–41', '["شرح فكرة الجلفانومتر ذي الملف المتحرك","حساب مقاومة مجزئ التيار لتحويله إلى أميتر"]', '[{"type": "text", "text": "الجلفانومتر ذو الملف المتحرك جهاز حساس يدل على التيارات الضعيفة جدًا ويحدد اتجاهها، وحساسيته هي انحراف المؤشر لكل وحدة تيار (درجة لكل ميكرو أمبير). لتحويله إلى أميتر نوصل بملفه على التوازي مقاومة صغيرة جدًا هي مجزئ التيار R_s، فيمر معظم التيار فيها ويمر في الملف I_g فقط عند نهاية التدريج. ولأن مقاومة الأميتر صغيرة لا يؤثر في الدائرة عند توصيله على التوالي."}, {"type": "formula", "tex": "R_s = \\dfrac{I_g R_g}{I - I_g}"}, {"type": "lab", "lab": "ammeter"}, {"type": "text", "text": "جرّب بنفسك: ارفع أقصى تيار I: يصغر R_s أكثر لأن الجزء الأكبر من التيار يجب أن يمر فيه."}]', 7, 'editorial', 'f5544f7e-917f-561f-a505-dc068c88a6c5');
insert into concepts (id, lesson_id, title_ar, explanation_ar, formula_tex, sort_order, origin) values ('cad17607-408d-5ba2-835f-8797784441e8', '51038a5c-37b2-5255-b73b-3277760dde6e', 'تحويل الجلفانومتر إلى أميتر', 'الجلفانومتر ذو الملف المتحرك جهاز حساس يدل على التيارات الضعيفة جدًا ويحدد اتجاهها، وحساسيته هي انحراف المؤشر لكل وحدة تيار (درجة لكل ميكرو أمبير). لتحويله إلى أميتر نوصل بملفه على التوازي مقاومة صغيرة جدًا هي مجزئ التيار R_s، فيمر معظم التيار فيها ويمر في الملف I_g فقط عند نهاية التدريج. ولأن مقاومة الأميتر صغيرة لا يؤثر في الدائرة عند توصيله على التوالي.', 'R_s = \dfrac{I_g R_g}{I - I_g}', 1, 'editorial');
