insert into lessons (id, unit_id, title_ar, overview_ar, objectives_ar, body, sort_order, origin, source_id) values ('5a28bfdb-b542-5f6a-b4c9-5b3abad1a1a7', 'dbf8af48-45ea-52f6-991a-31d7e595da89', 'تحويل الجلفانومتر إلى فولتميتر', 'الكتاب المدرسي ص 42–43', '["شرح تحويل الجلفانومتر إلى فولتميتر","حساب المقاومة المضاعفة للجهد"]', '[{"type": "text", "text": "الفولتميتر يقيس فرق الجهد بين نقطتين فيوصل على التوازي مع الجزء المراد قياسه، ولا يجب أن يسحب تيارًا ملحوظًا. لذلك نوصل بملف الجلفانومتر على التوالي مقاومة كبيرة جدًا تسمى المقاومة المضاعفة R_m. أقصى تيار في الملف I_g، والجهد الكلي ينقسم بين الملف والمضاعف."}, {"type": "formula", "tex": "R_m = \\dfrac{V - V_g}{I_g}"}, {"type": "lab", "lab": "voltmeter"}, {"type": "text", "text": "جرّب بنفسك: ارفع أقصى جهد V: تكبر R_m لأن الجهد الزائد كله يقع عليها تقريبًا."}]', 8, 'editorial', 'f5544f7e-917f-561f-a505-dc068c88a6c5');
insert into concepts (id, lesson_id, title_ar, explanation_ar, formula_tex, sort_order, origin) values ('398afd24-5336-52a2-8643-12de61045a22', '5a28bfdb-b542-5f6a-b4c9-5b3abad1a1a7', 'تحويل الجلفانومتر إلى فولتميتر', 'الفولتميتر يقيس فرق الجهد بين نقطتين فيوصل على التوازي مع الجزء المراد قياسه، ولا يجب أن يسحب تيارًا ملحوظًا. لذلك نوصل بملف الجلفانومتر على التوالي مقاومة كبيرة جدًا تسمى المقاومة المضاعفة R_m. أقصى تيار في الملف I_g، والجهد الكلي ينقسم بين الملف والمضاعف.', 'R_m = \dfrac{V - V_g}{I_g}', 1, 'editorial');
insert into questions (id, concept_id, prompt_ar, explanation_ar, difficulty, origin) values ('3d9d8c7d-6b4e-505e-b83e-1e47e8e6a937', '398afd24-5336-52a2-8643-12de61045a22', 'جلفانومتر مقاومة ملفه 34 Ω وأقصى تيار فيه 1 mA. احسب المقاومة المضاعفة اللازمة لتحويله إلى فولتميتر نهايته العظمى 10 V. الإجابة بوحدة Ω.', 'القانون المستخدم: R_m = (V − V_g) / I_g     V_g = I_g R_g. الناتج الصحيح 9966 Ω.', 1, 'editorial');
