insert into lessons (id, unit_id, title_ar, overview_ar, objectives_ar, body, sort_order, origin, source_id) values ('a5624e66-cb94-5b03-8d66-6ca1c248ef80', 'dbf8af48-45ea-52f6-991a-31d7e595da89', 'الأوميتر', 'الكتاب المدرسي ص 44–45', '["شرح فكرة عمل الأوميتر","ربط انحراف المؤشر بقيمة المقاومة المجهولة"]', '[{"type": "text", "text": "الأوميتر ميكرو أميتر موصول على التوالي مع مقاومة ثابتة وأخرى متغيرة وعمود جاف. عند تلامس الطرفين (R_x = 0) تضبط المقاومة المتغيرة ليبلغ المؤشر نهاية التدريج. وكلما زادت المقاومة المجهولة قل التيار وقل الانحراف، ولذلك فتدريجه معكوس واتساع أقسامه غير منتظم."}, {"type": "formula", "tex": "I = \\dfrac{V_B}{R_{int} + R_x}"}, {"type": "lab", "lab": "ohmmeter"}, {"type": "text", "text": "جرّب بنفسك: اضبط R_x على 3750 فينحرف المؤشر إلى منتصف التدريج، فهي تساوي مقاومة الجهاز الداخلية."}]', 9, 'editorial', 'f5544f7e-917f-561f-a505-dc068c88a6c5');
insert into concepts (id, lesson_id, title_ar, explanation_ar, formula_tex, sort_order, origin) values ('fdbb5040-232a-5db1-acea-646e6144df3f', 'a5624e66-cb94-5b03-8d66-6ca1c248ef80', 'الأوميتر', 'الأوميتر ميكرو أميتر موصول على التوالي مع مقاومة ثابتة وأخرى متغيرة وعمود جاف. عند تلامس الطرفين (R_x = 0) تضبط المقاومة المتغيرة ليبلغ المؤشر نهاية التدريج. وكلما زادت المقاومة المجهولة قل التيار وقل الانحراف، ولذلك فتدريجه معكوس واتساع أقسامه غير منتظم.', 'I = \dfrac{V_B}{R_{int} + R_x}', 1, 'editorial');
